local KTool = CS.Engine.Lib.KTool
local CommonPlayerHeadNode = "Game.Behaviours.CommonPlayerHeadNode"
local ChatConstants = import('Game.OverseaChat.ChatConstants')

--- from: Assets/BundleResources/Prefabs/OverseaChat/OverseaChatDialog.prefab
---@class OverseaChatTabCell
---@field Env                            OverseaChatTabCell
---@field controller                        Engine.Modules.LuaBehaviour
---@field CommonPlayerHeadNode            UnityEngine.RectTransform
---@field TextDescPlayer                    Game.Native.Common.UISwitchText
---@field Player                            UnityEngine.RectTransform
---@field TextDescOther                    Game.Native.Common.UISwitchText
---@field Other                            UnityEngine.RectTransform
---@field BtnNode                        UnityEngine.RectTransform
---@field ImgSelect                        UnityEngine.RectTransform
local OverseaChatTabCell = Class("OverseaChatTabCell")

function OverseaChatTabCell:__init()
    self.index = 0
    self.clickNodeCb = nil
    ---@type UnityEngine.RectTransform
    self.redPointOtherTrans = nil
    ---@type UnityEngine.RectTransform
    self.redPointPlayerTrans = nil
end

function OverseaChatTabCell:__delete()
    self.index = nil
    self.clickNodeCb = nil
    self.controller = nil
    self.redPointOtherTrans = nil
    ---@type UnityEngine.RectTransform
    self.redPointPlayerTrans = nil
end

function OverseaChatTabCell:Awake()
    self.redPointOtherTrans = self.Other.transform:Find("CommonRedPoint")
    self.redPointPlayerTrans = self.Player.transform:Find("CommonRedPoint")
    SetButtonAction(self.BtnNode, Bind(self, self.OnClickNode))
end

function OverseaChatTabCell:FreshSelectStatus(isSelected)
    KTool.SetActive(self.ImgSelect, isSelected)
    self.TextDescOther.Status = isSelected and 2 or 1
end

function OverseaChatTabCell:SetChannelInfo(index, name, channel)
    KTool.SetActive(self.Player.gameObject, false)
    KTool.SetActive(self.Other.gameObject, true)
    CfUtils.FillText(self.TextDescOther, name)
    self.index = index
    local social = AppService:GetInstance():GetSocialLine()
    if isNull(self.redPointOtherTrans) then return end
    
    if channel == ChatConstants.Channels.Private then
        local isHave = social:IsHaveUnreadMsgByPlayerId()
        KTool.SetActive(self.redPointOtherTrans.gameObject, checkBool(isHave))
    elseif channel == ChatConstants.Channels.Fight then
        local newMsg = social:CheckNewMessage(ChatConstants.ChatServerChannel.Fight)
        KTool.SetActive(self.redPointOtherTrans.gameObject, checkBool(newMsg))
    elseif channel == ChatConstants.Channels.Union then
        local newMsg = social:CheckNewMessage(ChatConstants.ChatServerChannel.Union)
        KTool.SetActive(self.redPointOtherTrans.gameObject, checkBool(newMsg))
    else
        KTool.SetActive(self.redPointOtherTrans.gameObject, false)
    end
end

function OverseaChatTabCell:FreshPlayerData(index, data, isSelected)
    self.index = index
    KTool.SetActive(self.Player.gameObject, true)
    KTool.SetActive(self.Other.gameObject, false)
    local selectTrans = self.Player.transform:Find("ImgSelect")
    if selectTrans then
        KTool.SetActive(selectTrans.gameObject, false)
    end
    local TextDescTrans = self.Player.transform:Find("TextDesc")
    if TextDescTrans then
        CfUtils.FillText(TextDescTrans.gameObject, tostring(data.name))
        local CommonPlayerHeadNodeTrans = self.Player.transform:Find("CommonPlayerHeadNode")
        ---@type CommonPlayerHeadNode
        local env = CfUtils.GetLuaScr(CommonPlayerHeadNodeTrans.gameObject, CommonPlayerHeadNode)
        if env then
            env:FreshAvatarFrame(data.avatar, data.avatarFrame)
        end
    end
    if not isSelected then
        local social = AppService:GetInstance():GetSocialLine()
        local isHave = social:IsHaveUnreadMsgByPlayerId(checkNumber(data.friendId))
        if self.redPointPlayerTrans then
            KTool.SetActive(self.redPointPlayerTrans.gameObject, checkBool(isHave))
        end
    else
        if self.redPointPlayerTrans then
            KTool.SetActive(self.redPointPlayerTrans.gameObject, false)
        end
    end
end

function OverseaChatTabCell:SetClickCb(cb)
    self.clickNodeCb = cb
end

function OverseaChatTabCell:OnClickNode()
    if self.clickNodeCb then
        self.clickNodeCb(self.index)
    end
end

function OverseaChatTabCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end
return OverseaChatTabCell